const SUPPORTED_METHODS=new Set(['ols','wls','robust']);
const DEFERRED_METHODS=new Set(['quantile']);
const OUT_OF_SCOPE_METHODS=new Set(['ridge','lasso','elasticnet','mixed','gls']);
