const n=predictors.length;
const y=predictors.map((row)=>row[j]);
const design=predictors.map((row)=>[1,...row.filter((unused,c)=>c!==j)]);
const fit=solveWls(design,y,null);
if(!fit)return 1;
const ybar=y.reduce((s,v)=>s+v,0)/n;
let rss=0;
