my/=n;
let sxy=0;
let sxx=0;
let syy=0;
for(let i=0;i<n;i++){
const dx=rx[i]-mx;
const dy=ry[i]-my;
sxy+=dx*dy;
sxx+=dx*dx;
syy+=dy*dy;
}
