function westernElectricViolations(ordered,limits){
if(!limits||!(limits.sigma>0))return[];
const n=ordered.length;
const{centre,sigma}=limits;
const z=(i)=>(ordered[i]-centre)/sigma;
const out=[];
for(let i=0;i<n;i++){
if(Math.abs(z(i))>3){
out.push({index:i,rule:1,description:'beyond three sigma'});
}
if(i>=2){
for(const side of[1,-1]){
let hits=0;
for(let k=i-2;k<=i;k++)if(z(k)*side>2)hits++;
if(hits>=2){
out.push({index:i,rule:2,description:'two of three past two sigma'});
break;
}
}
}
if(i>=4){
for(const side of[1,-1]){
let hits=0;
for(let k=i-4;k<=i;k++)if(z(k)*side>1)hits++;
if(hits>=4){
out.push({index:i,rule:3,description:'four of five past one sigma'});
break;
}
}
}
if(i>=7){
for(const side of[1,-1]){
let all=true;
for(let k=i-7;k<=i;k++)if(z(k)*side<=0){all=false;break;}
if(all){
out.push({index:i,rule:4,description:'eight in a row on one side'});
break;
}
}
}
}
return out;
}
function nelsonViolations(ordered,limits){
if(!limits||!(limits.sigma>0))return[];
const n=ordered.length;
const{centre,sigma}=limits;
const z=(i)=>(ordered[i]-centre)/sigma;
const oneSide=(from,to,past,need)=>{
for(const side of[1,-1]){
let hits=0;
for(let k=from;k<=to;k++)if(z(k)*side>past)hits++;
if(hits>=need)return true;
}
return false;
};
const out=[];
for(let i=0;i<n;i++){
if(Math.abs(z(i))>3)out.push({index:i,rule:1,description:'beyond three sigma'});
if(i>=8){
for(const side of[1,-1]){
let all=true;
for(let k=i-8;k<=i;k++)if(z(k)*side<=0){all=false;break;}
if(all){out.push({index:i,rule:2,description:'nine in a row on one side'});break;}
}
}
if(i>=5){
for(const dir of[1,-1]){
let all=true;
for(let k=i-4;k<=i;k++){
if((ordered[k]-ordered[k-1])*dir<=0){all=false;break;}
}
if(all){
out.push({index:i,rule:3,description:dir>0?'six rising':'six falling'});
break;
}
}
}
if(i>=13){
let alternating=true;
for(let k=i-12;k<=i;k++){
const a=ordered[k]-ordered[k-1];
const b=ordered[k+1<=i?k+1:k]-ordered[k];
if(k+1>i)break;
if(a===0||b===0||(a>0)===(b>0)){alternating=false;break;}
}
if(alternating)out.push({index:i,rule:4,description:'fourteen alternating'});
}
if(i>=2&&oneSide(i-2,i,2,2)){
out.push({index:i,rule:5,description:'two of three past two sigma'});
}
if(i>=4&&oneSide(i-4,i,1,4)){
out.push({index:i,rule:6,description:'four of five past one sigma'});
}
if(i>=14){
let inside=true;
for(let k=i-14;k<=i;k++)if(Math.abs(z(k))>=1){inside=false;break;}
if(inside)out.push({index:i,rule:7,description:'fifteen within one sigma'});
}
if(i>=7){
let outside=true;
for(let k=i-7;k<=i;k++)if(Math.abs(z(k))<=1){outside=false;break;}
if(outside)out.push({index:i,rule:8,description:'eight beyond one sigma'});
}
}
return out;
}
