const k=Number(successes);
const total=Number(n);
if(!(total>0)||!(k>=0)||k>total)return null;
const c=level(conf);
const z=normalQuantile(1-(1-c)/2);
const p=k/total;
const z2=z*z;
const denominator=1+z2/total;
const centre=(p+z2/(2*total))/denominator;
const half=(z/denominator)
*Math.sqrt((p*(1-p))/total+z2/(4*total*total));
